(function(root){
const sources=[{id:'civil',title:'中华人民共和国民法典',article:'第859、860条',agency:'国家市场监督管理总局转载',date:'2020-05-28',url:'https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/bgt/art/2023/art_60fb3863b7364b759123a42d1df568ca.html',summary:'委托开发与合作开发的专利申请权有不同默认规则，应通过合同明确成果归属。'},{id:'ai',title:'生成式人工智能服务管理暂行办法',article:'第2、7条',agency:'国家互联网信息办公室',date:'2023-07-13',url:'https://www.cac.gov.cn/2023-07/13/c_1690898327029107.htm',summary:'面向境内公众提供生成式人工智能服务时，应关注训练数据合法来源与知识产权要求；内部研发需另行判断适用范围。'}];
const defaults=[{id:'IP-001',title:'明确项目成果与背景知识产权边界',scenario:'全部',level:'高',enabled:true,source:'civil',keywords:['成果归属','背景知识产权'],note:'区分既有工具、项目定制成果、可复用组件，并列明许可范围。'},{id:'IP-002',title:'训练数据授权与用途限制',scenario:'AI 大模型',level:'高',enabled:true,source:'ai',keywords:['训练授权','数据来源'],note:'约定数据来源证明、训练用途、留存期限与删除机制。'},{id:'IP-003',title:'FDE 交付与复用范围',scenario:'FDE 驻场开发',level:'中',enabled:true,source:'civil',keywords:['交付清单','复用许可'],note:'FDE 为本 Demo 中的驻场工程交付场景；明确源码、文档、组件复用与退出移交。'}];
function draft(rule,role){const own=role==='甲方'?'定制项目成果归甲方所有；乙方保留背景知识产权并授予甲方履行项目所需的持续使用许可。':role==='乙方'?'乙方保留背景知识产权及通用组件；项目定制成果按交付清单约定，甲方取得约定业务范围内的使用许可。':'双方以附件分别列明背景知识产权、定制成果及使用许可，未经约定不得扩大使用范围。';return rule.id==='IP-002'?'双方应保证各自提供的数据具有合法来源和相应授权。未经数据提供方书面同意，不得将项目数据用于通用模型训练；应在终止后按约定删除并提供记录。':rule.id==='IP-003'?own+' 双方以附件明确交付清单、验收标准、复用许可及退出移交安排。':own;}
function review(text,scenario,role,rules){if(!text.trim())return [];return rules.filter(r=>r.enabled&&(r.scenario==='全部'||r.scenario===scenario)).map(r=>{const missing=r.keywords.filter(k=>!text.includes(k));return {...r,status:missing.length?'需复核':'待人工确认',missing,evidence:missing.length?'未检出明确表述：'+missing.join('、'):'已检出关键词，但尚未验证条款效力与上下文。',draft:draft(r,role),role};});}
const api={sources,defaults,draft,review};if(typeof module!=='undefined')module.exports=api;root.LegalEngine=api;
})(typeof window!=='undefined'?window:globalThis);
